--------------------------------------------------------------------------------
-- Resincroniza las secuencias IDENTITY con el maximo ID actual de cada tabla
--------------------------------------------------------------------------------
ALTER TABLE pais MODIFY id_pais GENERATED BY DEFAULT ON NULL AS IDENTITY (START WITH 4);
ALTER TABLE departamento MODIFY id_departamento GENERATED BY DEFAULT ON NULL AS IDENTITY (START WITH 33);
ALTER TABLE municipio MODIFY id_municipio GENERATED BY DEFAULT ON NULL AS IDENTITY (START WITH 81);
ALTER TABLE tipo_tienda MODIFY id_tipo_tienda GENERATED BY DEFAULT ON NULL AS IDENTITY (START WITH 5);
ALTER TABLE tipo_identificacion MODIFY id_tipo_identificacion GENERATED BY DEFAULT ON NULL AS IDENTITY (START WITH 4);
ALTER TABLE cargo MODIFY id_cargo GENERATED BY DEFAULT ON NULL AS IDENTITY (START WITH 5);
ALTER TABLE categoria MODIFY id_categoria GENERATED BY DEFAULT ON NULL AS IDENTITY (START WITH 11);
ALTER TABLE marca MODIFY id_marca GENERATED BY DEFAULT ON NULL AS IDENTITY (START WITH 16);
ALTER TABLE estado_venta MODIFY id_estado_venta GENERATED BY DEFAULT ON NULL AS IDENTITY (START WITH 4);
ALTER TABLE metodo_pago MODIFY id_metodo_pago GENERATED BY DEFAULT ON NULL AS IDENTITY (START WITH 5);
ALTER TABLE tienda MODIFY id_tienda GENERATED BY DEFAULT ON NULL AS IDENTITY (START WITH 21);
ALTER TABLE persona MODIFY id_persona GENERATED BY DEFAULT ON NULL AS IDENTITY (START WITH 389);
ALTER TABLE empleado MODIFY id_empleado GENERATED BY DEFAULT ON NULL AS IDENTITY (START WITH 89);
ALTER TABLE cliente MODIFY id_cliente GENERATED BY DEFAULT ON NULL AS IDENTITY (START WITH 301);
ALTER TABLE producto MODIFY id_producto GENERATED BY DEFAULT ON NULL AS IDENTITY (START WITH 115);
ALTER TABLE venta MODIFY id_venta GENERATED BY DEFAULT ON NULL AS IDENTITY (START WITH 1501);
ALTER TABLE pago MODIFY id_pago GENERATED BY DEFAULT ON NULL AS IDENTITY (START WITH 1390);